// AuditResource: Console audit log.
type AuditResource struct{ c *core }

// List: Console audit log of the calling environment, newest first.
func (r *AuditResource) List(ctx context.Context, query *AuditListQuery, opts ...RequestOption) (*AuditListData, error) {
	var out AuditListData
	if err := r.c.call(ctx, http.MethodGet, "/v1/audit-logs", toQuery(query), nil, &out, opts); err != nil {
		return nil, err
	}
	return &out, nil
}

