// services holds every operation and resource group of the Lowco API.
type services struct {
	// Barcode calls the /v1/barcode operations.
	Barcode *BarcodeService
	// DocAI calls the /v1/docai operations.
	DocAI *DocAIService
	// OCR calls the /v1/ocr operations.
	OCR *OCRService
	// PDF calls the /v1/pdf operations.
	PDF *PDFService
	// QR calls the /v1/qr operations.
	QR *QRService
	// Render calls the /v1/render operations.
	Render *RenderService
	// Verify calls the /v1/verify operations.
	Verify *VerifyService
	// Audit: Console audit log.
	Audit *AuditResource
	// Files: Uploaded and produced files.
	Files *FilesResource
	// Jobs: Asynchronous jobs.
	Jobs *JobsResource
	// Keys: .
	Keys *KeysResource
	// MessageTemplates: .
	MessageTemplates *MessageTemplatesResource
	// Messages: .
	Messages *MessagesResource
	// Otp: .
	Otp *OtpResource
	// Requests: .
	Requests *RequestsResource
	// Senders: .
	Senders *SendersResource
	// Settings: Environment settings.
	Settings *SettingsResource
	// Sign: .
	Sign *SignResource
	// SignTemplates: .
	SignTemplates *SignTemplatesResource
	// Suppressions: .
	Suppressions *SuppressionsResource
	// Templates: Stored render templates.
	Templates *TemplatesResource
	// Usage: Usage and balance.
	Usage *UsageResource
	// Webhooks: Webhook endpoints and deliveries.
	Webhooks *WebhooksResource
}

func newServices(c *core) services {
	return services{
		Barcode:          &BarcodeService{c},
		DocAI:            &DocAIService{c},
		OCR:              &OCRService{c},
		PDF:              &PDFService{c},
		QR:               &QRService{c},
		Render:           &RenderService{c},
		Verify:           &VerifyService{c},
		Audit:            &AuditResource{c},
		Files:            &FilesResource{c},
		Jobs:             &JobsResource{c},
		Keys:             &KeysResource{c},
		MessageTemplates: &MessageTemplatesResource{c},
		Messages:         &MessagesResource{c},
		Otp:              &OtpResource{c},
		Requests:         &RequestsResource{c},
		Senders:          &SendersResource{c},
		Settings:         &SettingsResource{c},
		Sign:             &SignResource{c},
		SignTemplates:    &SignTemplatesResource{c},
		Suppressions:     &SuppressionsResource{c},
		Templates:        &TemplatesResource{c},
		Usage:            &UsageResource{c},
		Webhooks:         &WebhooksResource{c},
	}
}
